function page(titulo, cuerpo){
  return '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>' + titulo + ' - Siemon Digital</title></head>'
    + '<body style="margin:0;background:#0A0B0D;color:#C7C8D0;font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:22px">'
    + '<div style="max-width:460px;text-align:center">'
    + '<div style="font-weight:800;letter-spacing:.16em;font-size:13px;color:#fff;text-transform:uppercase;margin-bottom:24px">SIEMON<span style="color:#B1A3E1">DIGITAL</span></div>'
    + cuerpo + '</div></body></html>';
}
function btn(href, txt, bg){ return '<a href="' + href + '" style="display:inline-block;background:' + bg + ';color:#0A0B0D;text-decoration:none;font-weight:700;padding:14px 30px;border-radius:999px;font-size:15px">' + txt + '</a>'; }
const q = $('Webhook aprobar').first().json.query || {};
const rec = $json || {}; const rf = rec.fields || rec;
const tokenRec = rf['Revision token'] || rec['Revision token'] || '';
let cliente = rf.Company || rf.Name || rec.Company || rec.Name || '';
if (!cliente) { try { const d = JSON.parse(rf['Datos formulario'] || rec['Datos formulario'] || '{}'); cliente = d.company || d.name || ''; } catch (e) {} }
if (!cliente) cliente = 'tu cliente';
const valid = q.t && tokenRec && String(q.t) === String(tokenRec);
if (!valid) {
  return [{ json: { action: 'respond', html: page('Enlace no valido', '<h1 style="color:#fff;font-size:22px;margin:0 0 10px">Enlace no valido o vencido</h1><p style="color:#9A9CA6;line-height:1.6">Este enlace ya no funciona. Si necesitas la propuesta, genera una nueva.</p>') } }];
}
if (String(q.confirm) !== '1') {
  const yes = 'https://hooks.siemondigital.com/webhook/aprobar-propuesta?email=' + encodeURIComponent(q.email || '') + '&t=' + encodeURIComponent(q.t) + '&confirm=1';
  return [{ json: { action: 'respond', html: page('Confirmar', '<h1 style="color:#fff;font-size:22px;margin:0 0 10px">Aprobar la propuesta de ' + cliente + '?</h1><p style="color:#9A9CA6;line-height:1.6;margin-bottom:26px">Al aprobar, queda lista para el cliente (la recibe cuando marques la videollamada como realizada).</p>' + btn(yes, 'Si, aprobar', '#77CBA1')) } }];
}
return [{ json: { action: 'approve', email: q.email, html: page('Aprobada', '<h1 style="color:#fff;font-size:22px;margin:0 0 10px">Propuesta aprobada</h1><p style="color:#9A9CA6;line-height:1.6">La propuesta de <b style="color:#C7C8D0">' + cliente + '</b> queda lista. El cliente la recibira al marcar la videollamada como realizada.</p>') } }];

